/* GROUP STANDARD · Readiness score = 70% Big 5 composite (average of the five domain scores, latest screening) + 30% independence in the last 4 lessons.
   Advanced ≥ 68 · Progressing 45–67 · Beginning < 45.  Today’s lesson feeds tomorrow’s plan; groups move only with completed lessons. */
const GRP_ADV=68,GRP_BEG=45;
function groupInfo(){const es=UI.lang==='es';const n={beg:0,pro:0,adv:0};KIDS.forEach(k=>{const l=kidLevel(k.id);if(l)n[l]++});
 return `<div class="infobox" style="margin:0 0 12px"><b>${es?'Cómo se forman los grupos':'How groups are set'}</b>
 <p style="margin:4px 0 8px">${es?'Puntaje de preparación = 70% Big 5 (promedio de los cinco dominios, último cernimiento) + 30% independencia en las últimas 4 lecciones. La lección de hoy alimenta el plan de mañana; los grupos cambian con lecciones completadas.':'Readiness score = 70% Big 5 (average of the five domains, latest screening) + 30% independence in the last 4 lessons. Today’s lesson feeds tomorrow’s plan; groups move only with completed lessons.'}</p>
 <div class="row" style="gap:8px"><span class="chip teal">${t('g_adv')} · 68+ · ${n.adv}</span><span class="chip blue">${t('g_pro')} · 45–67 · ${n.pro}</span><span class="chip gold">${t('g_beg')} · &lt;45 · ${n.beg}</span></div></div>`}
function pastLessons(kid){const c=b5avg(kid);if(c<0)return [];const r=rng(hash(kid+'-past'));return [0,1,2,3].map(i=>Math.max(5,Math.min(100,Math.round(c-8+i*3+(r()-.5)*8))))}
function kidScore(kid){const c=b5avg(kid);if(c<0)return null;const p=pastLessons(kid);return Math.round(.7*c+.3*p.reduce((a,b)=>a+b,0)/p.length)}
function kidLevel(kid){const sc=kidScore(kid);if(sc!=null)return sc>=GRP_ADV?'adv':sc<GRP_BEG?'beg':'pro';const c=kidSummary(kid);if(!c.n){const k=KID[kid];if(!k||k.live)return null;const a=b5avg(kid);if(a<0)return null;return a<40?'beg':a>=75?'adv':'pro'}if(c.no>=3||c.ok<c.n*.5)return 'beg';if(c.ok>=c.n*.8)return 'adv';return 'pro'}
function genPlanBoxes(){const es=UI.lang==='es';const P={boxes:{},groups:{beg:[],pro:[],adv:[]},kid:{},watch:[],family:null,focus:null};BOXES.forEach(b=>P.boxes[b.id]=[]);const add=(box,text,kind,why)=>P.boxes[box].push({text,kind:kind||'same',why});const nm=a=>a.map(k=>k.name).join(', ');
 KIDS.forEach(k=>{const lv=kidLevel(k.id);if(lv)P.groups[lv].push(k.id);P.kid[k.id]=[]});
 const regK=KIDS.filter(k=>['sup','no'].includes(getR(k.id,'reg_body')));const snd=counts('snd');const sk=KIDS.filter(k=>getR(k.id,'snd')&&getR(k.id,'snd')!=='ok');
 const wc=WORDS.map(w=>({w,c:counts('w_'+w.id)})).filter(x=>x.c.n);const low=wc.filter(x=>x.c.ok<x.c.n/2);const hi=wc.filter(x=>x.c.ok>=x.c.n*.75);
 const ret=counts('retell');const retK=KIDS.filter(k=>getR(k.id,'retell')&&getR(k.id,'retell')!=='ok');const wd=KIDS.filter(k=>getR(k.id,'word')&&getR(k.id,'word')!=='ok');const bkK=KIDS.filter(k=>getR(k.id,'bk')&&getR(k.id,'bk')!=='ok');
 const wn=KIDS.filter(k=>['sup','no'].includes(getR(k.id,'wings')));const tn=KIDS.filter(k=>['sup','no'].includes(getR(k.id,'turn')));const lead=P.groups.adv.slice(0,2).map(id=>KID[id]);
 const lows=BIG5.map(d=>({d,a:classDomAvg(d.id)})).filter(x=>x.a).sort((a,b)=>a.a-b.a);const lo=lows[0];P.focus=lo?lo.d.id:null;const beg=lo?KIDS.filter(k=>domLevel(k.id,lo.d.id).lv<=1):[];
 /* 1 intro */ add('intro',es?'Saludo por nombre · caritas':'Greeting by name · feelings');if(regK.length)add('intro',es?`${nm(regK)}: agenda visual a la vista antes del saludo`:`${nm(regK)}: visual schedule up before the greeting`,'chg',es?`${regK.length} necesitaron apoyo para «cuerpo listo»`:`${regK.length} needed support for “ready body”`);
 /* 2 today */ add('today',es?'Seis imanes · señala · nombra':'Six magnets · point · name');if(lo&&lo.d.id==='cp')add('today',es?'Imán extra: «Recontar» después de Leer':'Extra magnet: “Retell” after Read','new',es?'Comprensión es el dominio Big 5 más bajo':'Comprehension is the lowest Big 5 domain');
 /* 3 ready */ if(regK.length){add('ready',es?`Opción sentada en voz alta · ${nm(regK)} con adulto al lado y Cinco dedos`:`Seated option aloud · ${nm(regK)} with an adult beside and Five-Finger Breathing`,'chg',es?`${regK.length} de ${counts('reg_body').n} con apoyo`:`${regK.length} of ${counts('reg_body').n} with support`);regK.forEach(k=>P.kid[k.id].push(es?'Empieza sentado/a · Cinco dedos':'Starts seated · Five-Finger Breathing'))}else add('ready',es?'Rutina de Pep · Noto 3·2·1 · Cinco dedos':'Pep’s routine · Notice 3·2·1 · Five-Finger Breathing');
 const noah=KID.noah;if(noah&&getR('noah','reg_body')&&getR('noah','reg_body')!=='ok'){add('ready',es?'Noah: March in Place 30 s antes de la alfombra':'Noah: March in Place 30 s before the rug','new',es?'Apoyo de su perfil':'From his profile');P.kid.noah.push('March in Place')}
 /* 4 sounds */ if(snd.n&&snd.ok<snd.n/2){add('sounds',es?`/K/ y /T/ primero con pista táctil y espejo · ${nm(sk.slice(0,4))}${sk.length>4?' +'+(sk.length-4):''}`:`/K/ and /T/ first with tactile cue and mirror · ${nm(sk.slice(0,4))}${sk.length>4?' +'+(sk.length-4):''}`,'chg',`${snd.ok}/${snd.n} ✓`);sk.forEach(k=>P.kid[k.id].push(es?'Sonidos con pista táctil':'Sounds with tactile cue'))}else add('sounds',es?'Cuatro sonidos · pista táctil · objeto':'Four sounds · tactile cue · object');
 if(low.length){add('sounds',es?`Volver a enseñar ${low.map(x=>x.w.en).join(' + ')} · tarjeta táctil + gesto; las demás, repaso rápido`:`Reteach ${low.map(x=>x.w.en).join(' + ')} · tactile card + gesture; quick review of the rest`,'chg',low.map(x=>`${x.w.en} ${x.c.ok}/${x.c.n} ✓`).join(' · '));KIDS.forEach(k=>{const miss=low.filter(x=>getR(k.id,'w_'+x.w.id)!=='ok').map(x=>x.w.en);if(miss.length)P.kid[k.id].push((es?'Repasar ':'Review ')+miss.join(', '))})}else add('sounds',es?'Cinco palabras · ver · decir · gesto · tocar':'Five words · see · say · gesture · touch');
 if(lo&&['pa','ak','ol'].includes(lo.d.id)){const F={pa:{es:'Aplaudir los nombres del salón y a-mi-gos antes de las tarjetas',en:'Clap classmates’ names and a-mi-gos before the cards'},ak:{es:'Buscar la primera letra del propio nombre en K, T, F, N',en:'Find the first letter of your own name among K, T, F, N'},ol:{es:'Frase de dos palabras con cada tarjeta («my turn», «mi amigo»)',en:'Two-word phrase with every card (“my turn”, “mi amigo”)'}};add('sounds',`Big 5 · ${L(F[lo.d.id])}`,'new',`${L(lo.d.n)} ${lo.a.toFixed(1)}/4${beg.length?' · '+nm(beg):''}`)}
 /* 5 book */ if(low.length||ret.n&&ret.ok<ret.n/2){add('book',es?`Releer solo pp. ${low.some(x=>['next','turn'].includes(x.w.id))?'3–5':'1, 6'} · tres imágenes fuera de orden en cada mesa · ${nm(retK.slice(0,4))}`:`Re-read pp. ${low.some(x=>['next','turn'].includes(x.w.id))?'3–5':'1, 6'} only · three pictures out of order at every table · ${nm(retK.slice(0,4))}`,'chg',es?`Recuento: ${ret.ok}/${ret.n} ✓`:`Retell: ${ret.ok}/${ret.n} ✓`);retK.forEach(k=>P.kid[k.id].push(es?'Recuento con tres imágenes':'Retell with three pictures'))}else add('book',es?'Libro completo · NEXT? antes de cada página':'Whole book · NEXT? before every page');
 /* 6 sentences */ if(hi.length)add('sentences',es?`De palabra a frase con ${hi.map(x=>x.w.en).join(', ')} · imanes WE · ARE · FRIENDS`:`Word to phrase with ${hi.map(x=>x.w.en).join(', ')} · WE · ARE · FRIENDS magnets`,'new',es?`${hi.length} palabra(s) ≥75 %`:`${hi.length} word(s) ≥75%`);add('sentences',wd.length?(es?`Elección de dos tarjetas · ${nm(wd)} · CAA precargado`:`Choice of two cards · ${nm(wd)} · AAC pre-loaded`):(es?'Tres niveles · escribir · dictar · armar':'Three levels · write · dictate · build'),wd.length?'chg':'same',wd.length?`${wd.length} ${es?'sin palabra sin modelo':'no word without a model'}`:null);wd.forEach(k=>P.kid[k.id].push(es?'Elección de dos para la palabra':'Choice of two for the word'));
 /* 7 fly */ add('fly',bkK.length?(es?`Fotos reales del salón (con autorización) · ${nm(bkK)}`:`Real classroom photos (with releases) · ${nm(bkK)}`):(es?'Transición · alas de ángel':'Transition · Angel Wings'),bkK.length?'chg':'same',bkK.length?(es?`${bkK.length} no nombraron un amigo o ayudante`:`${bkK.length} did not name a friend or helper`):null);
 /* 8 exercise */ if(wn.length||lead.length){add('exercise',es?`${lead.length?nm(lead)+' lideran la Zancada al frente · ':''}${wn.length?nm(wn)+' con adulto modelando · ':''}Marcha o rodilla arriba en parejas`:`${lead.length?nm(lead)+' lead the Forward Lunge · ':''}${wn.length?nm(wn)+' with an adult modeling · ':''}March or Knee Lift in pairs`,'chg',`${counts('wings').ok}/${counts('wings').n} ✓`);wn.forEach(k=>P.kid[k.id].push(es?'Adulto modela Ready Your Wings':'Adult models Ready Your Wings'));lead.forEach(k=>P.kid[k.id].push(es?'Lidera un movimiento':'Leads a move'))}else add('exercise','Ready Your Wings · 5 moves');
 if(tn.length>=3){add('exercise',es?`First/Next: dos rondas más · ${nm(tn.slice(0,3))} con traspaso del adulto y 5 s`:`First/Next: two more rounds · ${nm(tn.slice(0,3))} with adult hand-off and 5 s`,'chg',`${tn.length}/${counts('turn').n} ${es?'con recordatorio':'with a reminder'}`);tn.forEach(k=>P.kid[k.id].push('First/Next · 5 s'))}
 /* 9 closing */ add('closing',es?'Respiración · caritas · promesa':'Breathing · faces · pledge');const aac=KIDS.filter(k=>k.modes.includes('aac')||k.modes.includes('sign'));if(aac.length)add('closing',es?`Promesa con símbolos y señas · ${nm(aac)}`:`Pledge with symbols and signs · ${nm(aac)}`,'new',es?'Modo de respuesta del perfil':'Response mode from the profile');
 KIDS.filter(k=>k.id==='valentina'||k.id==='liam').forEach(k=>P.kid[k.id].push(k.home==='es'?(es?'Español primero, luego inglés':'Spanish first, then English'):(es?'Inglés primero, eco en español':'English first, Spanish echo')));
 if(lo)beg.forEach(k=>P.kid[k.id].push(`Big 5 · ${L(lo.d.n)} · ${es?'grupo pequeño 5 min':'5-min small group'}`));
 P.watch=[...new Set([...regK,...sk,...retK,...wd,...wn].map(k=>k.id))].slice(0,5).map(id=>({id,what:P.kid[id][0]||''}));
 P.family=low.length?{es:`En casa: busquen «${low[0].w.en} / ${low[0].w.es}» en un cuento y hagan el gesto (${L(low[0].w.gesture)}).`,en:`At home: find “${low[0].w.en} / ${low[0].w.es}” in a story and do the gesture (${L(low[0].w.gesture)}).`}:{es:'En casa: «mi turno · tu turno» con un juego de mesa.',en:'At home: “my turn · your turn” with a board game.'};
 return P}
