 const right=`<span class="chip gold" style="font-size:.95em;padding:10px 16px;background:#FFF6D6;color:#6a4300">${nchg} ${t('changes')}</span><button class="btn white" data-act="edit">${S.editing?'✓ '+t('done_edit'):ico('edit',15)+' '+t('edit')}</button><button class="btn teal" data-act="saveplan">${S.savedPlan?'✓ ':''}${t('save')}</button>`;
