function litPct(kid,langs){let sum=0,app=0;SITEMS.filter(i=>i.d==='LC'||i.d==='LIT').forEach(i=>{const v=getB5(kid,i.id,'i');if(!v||v.s==null||v.p==='declined')return;if(langs&&!langs.includes(v.l))return;app++;sum+=v.s});return app?Math.round(100*sum/(2*app)):null}
function domPct(kid,dk){return elofDomScore(kid,dk,'i').pct}
function partPct(kid){let n=0,f=0;SITEMS.forEach(i=>{const v=getB5(kid,i.id,'i');if(!v||!v.p)return;n++;if(v.p==='full')f++;else if(v.p==='partial')f+=.5});return n?Math.round(100*f/n):null}
function topKey(kid,f){const c={};SITEMS.forEach(i=>{const v=getB5(kid,i.id,'i');if(v&&v[f])c[v[f]]=(c[v[f]]||0)+1});return Object.entries(c).sort((a,b)=>b[1]-a[1])[0]?.[0]||null}
