/* support tags derived from each profile (real data), shown as icon chips */
const SUPTAGS={regulation:{en:'Regulation',es:'Regulación',ic:'wave',c:'#5B389A',bg:'#F0EAF9'},language:{en:'Language',es:'Lenguaje',ic:'book',c:'#1F67A8',bg:'#E8F2FB'},motor:{en:'Motor',es:'Motor',ic:'child',c:'#157A6E',bg:'#E3F5F2'},communication:{en:'Communication',es:'Comunicación',ic:'people',c:'#157A6E',bg:'#E3F5F2'},focus:{en:'Focus',es:'Enfoque',ic:'clock',c:'#B8780A',bg:'#FFF6D6'},visual:{en:'Visual',es:'Visual',ic:'search',c:'#B52A36',bg:'#FDEAEC'}};
const MODETAG={speech:{en:'Speech',es:'Habla',ic:'speech'},aac:{en:'AAC',es:'CAA',ic:'tablet'},gesture:{en:'Gesture',es:'Gesto',ic:'hand'},sign:{en:'Sign',es:'Señas',ic:'sign'},point:{en:'Points',es:'Señala',ic:'point'}};
function supTags(k){const tags=[];const add=x=>{if(!tags.includes(x))tags.push(x)};k.sup.forEach(s=>{const e=(s.en||'').toLowerCase();if(/schedule|quiet|breathing|regulat|warn before|predictable/.test(e))add('regulation');if(/spanish|english|bilingual|echo/.test(e))add('language');if(/seated|wheelchair|reach|move/.test(e))add('motor');if(/aac|gesture|sign|pointing|device/.test(e))add('communication');if(/wait|partner|march/.test(e))add('focus');if(/visual|tactile|cards|photo|hearing|facing/.test(e))add('visual')});return tags.slice(0,2)}
function supChips(k){const m=MODETAG[k.modes[0]];return `<span class="tagchip" style="--c:#1F67A8;--bg:#E8F2FB">${ico(m.ic,14)} ${L(m)}</span>`+supTags(k).map(x=>{const t_=SUPTAGS[x];return `<span class="tagchip" style="--c:${t_.c};--bg:${t_.bg}">${ico(t_.ic,14)} ${L(t_)}</span>`}).join('')}
function b5bars(kid){return `<span class="b5bars">${BIG5.map(d=>{const l=domLevel(kid,d.id,'i');return `<i title="${L(d.n)} · ${l.lv?t('lv'+l.lv):'—'}" style="--c:${B5COLOR[d.id]}"><b style="width:${l.lv?l.lv*25:0}%"></b></i>`}).join('')}</span>`}
function b5avg(kid){const v=BIG5.map(d=>domLevel(kid,d.id,'i').pct).filter(x=>x);return v.length?v.reduce((a,b)=>a+b,0)/v.length:-1}
function rosterVal(k,key){const c=kidSummary(k.id);switch(key){case 'name':return k.name;case 'group':return {beg:1,pro:2,adv:3}[kidLevel(k.id)]||0;case 'b5':return b5avg(k.id);case 'sup':return k.sup.length;case 'circ':return L(k.tag);case 'les':return litPct(k.id,['es','both'])??-1;case 'len':return litPct(k.id,['en','both'])??-1;case 'either':return litPct(k.id,null)??-1;case 'se':return domPct(k.id,'SE')??-1;case 'ef':return domPct(k.id,'ATL')??-1;case 'part':return partPct(k.id)??-1;case 'resp':return topKey(k.id,'l')||'';case 'today':return c.n?c.ok/c.n:-1}return 0}
