 const add=S.addOpen?`<div class="card" style="padding:12px 16px;margin-bottom:12px;display:flex;gap:8px;flex-wrap:wrap;align-items:center"><input id="addName" placeholder="${t('name_ph')}" maxlength="24" style="padding:10px 12px;border:1.5px solid var(--line);border-radius:10px;min-width:180px"><select id="addAge" style="padding:10px;border:1.5px solid var(--line);border-radius:10px"><option>4</option><option selected>5</option><option>6</option></select><select id="addHome" style="padding:10px;border:1.5px solid var(--line);border-radius:10px"><option value="es">Español</option><option value="en">English</option><option value="bi">ES + EN</option></select><select id="addMode" style="padding:10px;border:1.5px solid var(--line);border-radius:10px"><option value="speech">${es?'Habla':'Speech'}</option><option value="point">${es?'Señala':'Points'}</option><option value="aac">AAC</option><option value="sign">${es?'Señas':'Signs'}</option></select><button class="btn teal" data-act="add-save">${t('add')}</button><button class="btn ghost" data-act="add-close">✕</button></div>`:'';
