/* lesson-check value: today's recorded result, else a stable sample from recent lessons */
function litVal(kid,it){const v=getR(kid,it.id);if(v)return v;const k=KID[kid];if(!k||k.live)return null;const dl=it.b5?domLevel(kid,it.b5,'i'):null;const dp=dl&&dl.app?dl.pct:b5avg(kid);const base=Math.max(.04,Math.min(.98,dp/100));const x=rng(hash(kid+it.id+'-past'))();return x<base*.85?'ok':x<base*.85+.32?'sup':'no'}
function litSeeded(kid){return !ITEMS.some(it=>getR(kid,it.id))}
const DTIP={bk:{box:2,en:'Name one real school helper before the story, then connect it to the words',es:'Nombra a un ayudante real de la escuela antes del cuento y conéctalo con las palabras'},ol:{box:4,en:'Two-word phrase with every word card (WE + FRIEND), accept any mode',es:'Frase de dos palabras con cada tarjeta (WE + FRIEND); acepta cualquier modo'},pa:{box:4,en:'Clap the syllables and give the tactile cue before the sound',es:'Aplaude las sílabas y da la pista táctil antes del sonido'},ak:{box:5,en:'Find the first letter of their name in the Big Book and trace it',es:'Encuentra la primera letra de su nombre en el Big Book y trázala'},cp:{box:5,en:'Retell with the First · Next · Last strip and point to each page',es:'Recuenta con la tira Primero · Luego · Último y señala cada página'}};
function kidAdvice(k){const es=UI.lang==='es';const lv=kidLevel(k.id);const sc=kidScore(k.id);const past=pastLessons(k.id);
 const ds=BIG5.map(d=>({d,l:domLevel(k.id,d.id,'i')})).filter(x=>x.l.app).sort((a,b)=>a.l.pct-b.l.pct);const low=ds[0],high=ds[ds.length-1];
 const lvn=n=>t('lv'+n);const bn=n=>L(BOXES.find(b=>b.n===n).t);
 const st={ok:es?'Independiente':'Independent',sup:es?'Con apoyo':'With support',no:es?'Aún no':'Not yet'};
 const out=[];
 if(low){const its=ITEMS.filter(i=>i.b5===low.d.id);const gaps=its.map(i=>({i,v:litVal(k.id,i)})).filter(x=>x.v&&x.v!=='ok');const tip=DTIP[low.d.id];
  out.push({box:tip.box,h:es?'Enfoque: '+L(low.d.n):'Focus: '+L(low.d.n),a:es?tip.es:tip.en,why:[`Big 5 · ${L(low.d.n)} ${low.l.pct}% (${lvn(low.l.lv)}, ${es?'nivel':'level'} ${low.l.lv}/4) · ${es?'el más bajo de 5':'lowest of 5'}`].concat(gaps.slice(0,2).map(x=>`${litSeeded(k.id)?(es?'Lecciones recientes':'Recent lessons'):(es?'Hoy':'Today')} · ${L(x.i.lab).split(' · ')[0]} · ${st[x.v]}`))})}
 const m={};SITEMS.forEach(i=>{const v=getB5(k.id,i.id,'i');if(v&&v.l)m[v.l]=(m[v.l]||0)+1});const mt=Object.values(m).reduce((a,b)=>a+b,0)||1;const top=Object.entries(m).sort((a,b)=>b[1]-a[1])[0];
 const sp={};SITEMS.forEach(i=>{const v=getB5(k.id,i.id,'i');if(v&&v.sup)sp[v.sup]=(sp[v.sup]||0)+1});const topS=Object.entries(sp).sort((a,b)=>b[1]-a[1])[0];
 const sup0=k.sup&&k.sup[0];
 out.push({box:null,h:es?'Apoyos que usar':'Supports to use',a:sup0?L(sup0):(es?'Mantén las opciones de respuesta abiertas: hablar, señalar, gesto, seña o CAA':'Keep every response option open: speak, point, gesture, sign or AAC'),why:[top?`${es?'Responde con':'Mostly responds by'} ${L(RESP[top[0]])} · ${Math.round(100*top[1]/mt)}% ${es?'de los ítems':'of screening items'}`:null,topS?`${es?'Apoyo más frecuente':'Most common support'} · ${L(SUPL[topS[0]])} · ${Math.round(100*topS[1]/(Object.values(sp).reduce((a,b)=>a+b,0)||1))}%`:null,sup0?(es?'Apoyo del perfil':'Profile support'):null].filter(Boolean)});
 if(high&&high!==low){out.push({box:7,h:es?'Fortaleza para construir':'Strength to build on',a:es?`Da un rol de líder en ${bn(7)}: pide a ${k.name} que muestre el movimiento o elija el siguiente turno`:`Give ${k.name} a leader role in ${bn(7)}: show the move or pick the next turn`,why:[`Big 5 · ${L(high.d.n)} ${high.l.pct}% (${lvn(high.l.lv)}, ${es?'nivel':'level'} ${high.l.lv}/4)`]})}
 const trend=past.length?past[past.length-1]-past[0]:0;const gname=lv?t('g_'+lv):'—';
 out.push({box:lv==='adv'?6:lv==='beg'?3:null,h:es?'Ritmo de mañana':'Pace for tomorrow',a:lv==='adv'?(es?'Extiende: marco «We are… because…» y una palabra nueva':'Extend: the “We are… because…” frame and one new word'):lv==='beg'?(es?'Repite las mismas palabras 2 días, con la misma pista':'Repeat the same words for 2 days with the same cue'):(es?'Mantén el plan y sube una pista: de modelo a visual':'Keep the plan and fade one cue: model to visual'),why:[`${es?'Grupo':'Group'} · ${gname} · ${es?'puntaje':'score'} ${sc}`,past.length?`${es?'Últimas 4 lecciones sin apoyo':'Last 4 lessons independent'} · ${past.join('% → ')}% (${trend>=0?'+':''}${trend})`:null].filter(Boolean)});
 return out}
